ALTER TABLE public.support_settings ADD COLUMN ai_silence_queue_enabled boolean NOT NULL DEFAULT false;
COMMENT ON COLUMN public.support_settings.ai_silence_queue_enabled IS 'Keep false until managed 2-minute HTTP scheduling is available and verified; preserves existing immediate live trigger.';
CREATE OR REPLACE FUNCTION public.support_cost_recent_order(p_phone text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT length(regexp_replace(p_phone,'\D','','g'))>=8 AND (EXISTS(SELECT 1 FROM public.pos_sales WHERE phone_suffix8=right(regexp_replace(p_phone,'\D','','g'),8) AND created_at>=now()-interval '60 days') OR EXISTS(SELECT 1 FROM public.customers c JOIN public.orders o ON o.customer_id=c.id WHERE right(regexp_replace(coalesce(c.whatsapp,''),'\D','','g'),8)=right(regexp_replace(p_phone,'\D','','g'),8) AND o.created_at>=now()-interval '60 days')) $$;
CREATE OR REPLACE FUNCTION public.support_ai_enqueue(p_message_row_id uuid,p_phone text,p_number_id uuid,p_channel text,p_text text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$
DECLARE st public.support_settings%ROWTYPE; v_id uuid; k text; old public.support_auto_suggestions%ROWTYPE;
BEGIN
 SELECT * INTO st FROM public.support_settings LIMIT 1;
 IF st.auto_reply_mode<>'shadow' OR p_number_id IS NULL OR NOT(p_number_id=ANY(st.auto_reply_instance_ids)) THEN RETURN NULL; END IF;
 IF coalesce(p_text,'') !~ '[[:alnum:]]' OR public.support_cost_human(p_phone,p_channel) THEN RETURN NULL; END IF;
 k:=CASE WHEN coalesce(p_channel,'whatsapp')='whatsapp' THEN 'wa:'||right(regexp_replace(p_phone,'\D','','g'),8) ELSE 'ig:'||p_phone END;
 PERFORM pg_advisory_xact_lock(hashtextextended('support_cost:'||k,0));
 SELECT * INTO old FROM public.support_auto_suggestions WHERE cost_key=k AND status='processando' ORDER BY created_at DESC LIMIT 1 FOR UPDATE;
 IF FOUND AND old.created_at>now()-interval '5 minutes' THEN
 IF st.ai_silence_queue_enabled AND old.cost_claimed_at IS NULL THEN UPDATE public.support_auto_suggestions SET incoming_text=left(coalesce(incoming_text,'')||E'\n'||p_text,4000),message_row_id=p_message_row_id,phone=p_phone,whatsapp_number_id=p_number_id,cost_due_at=now()+interval '2 minutes' WHERE id=old.id; END IF;
 RETURN old.id;
 END IF;
 IF NOT public.support_cost_keywords(p_text) AND NOT public.support_cost_recent_order(p_phone) THEN RETURN NULL; END IF;
 INSERT INTO public.support_auto_suggestions(message_row_id,whatsapp_number_id,channel,phone,incoming_text,intent,decision,reason,mode_at_creation,ai_status,status,cost_key,cost_due_at)
 VALUES(p_message_row_id,p_number_id,coalesce(p_channel,'whatsapp'),p_phone,left(p_text,4000),coalesce(public.support_classify_intent(p_text),'indefinido'),'fila','aguardando_ia','shadow','pendente','processando',k,now()+CASE WHEN st.ai_silence_queue_enabled THEN interval '2 minutes' ELSE interval '0' END) ON CONFLICT(message_row_id) DO NOTHING RETURNING id INTO v_id;
 IF v_id IS NOT NULL AND NOT st.ai_silence_queue_enabled THEN PERFORM net.http_post(url:='https://tqxhcyuxgqbzqwoidpie.supabase.co/functions/v1/support-ai-agent',headers:=jsonb_build_object('Content-Type','application/json','x-cron-secret',(SELECT value FROM public.internal_function_secrets WHERE key='cron_secret')),body:=jsonb_build_object('suggestion_id',v_id),timeout_milliseconds:=60000); END IF;
 RETURN v_id;
END $$;
CREATE OR REPLACE FUNCTION public.support_cost_claim_direct(p_id uuid) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.support_auto_suggestions%ROWTYPE; d date:=(now() AT TIME ZONE 'America/Sao_Paulo')::date; BEGIN SELECT * INTO s FROM public.support_auto_suggestions WHERE id=p_id FOR UPDATE; IF NOT FOUND OR s.status<>'processando' OR s.cost_claimed_at IS NOT NULL OR s.cost_due_at>now() THEN RETURN false; END IF; IF public.support_cost_human(s.phone,s.channel) OR (NOT public.support_cost_keywords(s.incoming_text) AND NOT public.support_cost_recent_order(s.phone)) THEN UPDATE public.support_auto_suggestions SET status='ignorada',reason='pre_filtro_ao_processar' WHERE id=p_id; RETURN false; END IF; UPDATE public.support_auto_suggestions SET cost_claimed_at=now(),cost_prefilter_passed=true WHERE id=p_id; INSERT INTO public.support_ai_daily(day,prefiltered) VALUES(d,1) ON CONFLICT(day) DO UPDATE SET prefiltered=support_ai_daily.prefiltered+1; RETURN true; END $$;
REVOKE ALL ON FUNCTION public.support_cost_claim_direct(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.support_cost_claim_direct(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.support_shadow_action_guard(p_id uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF (SELECT auto_reply_mode FROM public.support_settings LIMIT 1)='shadow' OR EXISTS(SELECT 1 FROM public.support_auto_suggestions WHERE id=p_id AND mode_at_creation='shadow') THEN RAISE EXCEPTION 'Modo sombra: nenhum envio, link ou movimento permitido'; END IF; END $$;
REVOKE ALL ON FUNCTION public.support_shadow_action_guard(uuid) FROM PUBLIC,anon,authenticated; GRANT EXECUTE ON FUNCTION public.support_shadow_action_guard(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.support_suggestion_route(p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s record; BEGIN IF NOT public._exchange_desk_staff(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF; PERFORM public.support_shadow_action_guard(p_id); SELECT * INTO s FROM public.support_auto_suggestions WHERE id=p_id FOR UPDATE; IF NOT FOUND THEN RAISE EXCEPTION 'Sugestão não encontrada'; END IF; IF s.channel<>'whatsapp' THEN RAISE EXCEPTION 'Só conversas de WhatsApp têm linha de Suporte'; END IF; IF NOT public._support_move_to_support_line(s.phone,s.whatsapp_number_id,auth.uid()) THEN RAISE EXCEPTION 'Telefone inválido'; END IF; UPDATE public.support_auto_suggestions SET routed_at=now(),routed_by=auth.uid(),routed_auto=false WHERE id=p_id; RETURN jsonb_build_object('ok',true); END $$;
CREATE OR REPLACE FUNCTION public.support_suggestion_prepare_link(p_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.support_auto_suggestions%ROWTYPE; BEGIN IF NOT public._exchange_desk_staff(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF; PERFORM public.support_shadow_action_guard(p_id); SELECT * INTO s FROM public.support_auto_suggestions WHERE id=p_id FOR UPDATE; IF NOT FOUND OR s.status<>'nova' THEN RAISE EXCEPTION 'Sugestão não está aberta'; END IF; IF s.decision<>'enviar_link' OR s.sale_id IS NULL OR s.link_type IS NULL THEN RETURN NULL; END IF; RETURN public.create_support_link(s.sale_id::text,s.link_type,'agent',s.phone); END $$;
CREATE OR REPLACE FUNCTION public.support_suggestion_mark_sent(p_id uuid,p_text text,p_link_id uuid DEFAULT NULL) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public._exchange_desk_staff(auth.uid()) THEN RAISE EXCEPTION 'forbidden'; END IF; PERFORM public.support_shadow_action_guard(p_id); UPDATE public.support_auto_suggestions SET status='enviada',sent_text=left(p_text,2000),sent_link_id=p_link_id,sent_by=auth.uid(),sent_at=now() WHERE id=p_id AND status='nova'; IF NOT FOUND THEN RAISE EXCEPTION 'Sugestão não está aberta'; END IF; END $$;